        f = st.m.font(theme.FS_UI)
        st.m.draw_text(p, x + 28, y + (self.HEAD - st.m.line_h(f)) / 2, self.label, f, QColor(t.text))
        cx = x + 28 + st.m.text_w(self.label, f) + 7
        chevron(
            p,
            int(cx),
