        bf = QTextBlockFormat()
        bf.setLeftMargin(ind)
        bf.setTextIndent(-ind)
        bf.setLineHeight(self._code_line, QTextBlockFormat.LineHeightTypes.MinimumHeight.value)
        return bf

    def _code_cf(self, style: str, fg: Optional[str]) -> QTextCharFormat:
        colour = fg
        italic = False
