        self.scan_lay = vbox(self.scan_list, 2)
        self.scan_list.hide()
        self.scan_box.lay.addWidget(self.scan_list)
        sr = QWidget()
        srl = QHBoxLayout(sr)
        srl.setContentsMargins(0, 0, 0, 0)
        srl.setSpacing(8)
