        nl = QVBoxLayout(self.needs_sec)
        nl.setContentsMargins(0, 0, 0, 0)
        nl.setSpacing(10)
        self.needs_head = SectionHead("Needs you", glyph=True, end_text="Press 1, 2 or 3 to answer the first")
