            "Compacted — the context is a summary now; its size is measured at the next reply"
            if after_compact
            else f'<b style="color:{t.text}; font-weight:600">{tokens(used)}</b> of {tokens(total)} tokens'
            if total
            else f"{tokens(used)} of {tokens(total)}"
        )
        sl.addWidget(self.gauge_line)
        stats = QHBoxLayout()
        stats.setSpacing(8)
        stats.addWidget(StatTile("Cost so far", cost(float(usage.get("costUsd") or 0))))
        stats.addWidget(StatTile("Output tokens", tokens(int(usage.get("outputTokens") or 0))))
        sl.addLayout(stats)
        rl.addWidget(side, 1)
        s.add(row)
        if self.usage:
            cats = QWidget()
            cl = QVBoxLayout(cats)
            cl.setContentsMargins(0, 0, 0, 0)
            cl.setSpacing(5)
            bar = CatBar()
            bar.set_usage(self.usage)
            bar.setContentsMargins(0, 0, 0, 1)
            cl.addWidget(bar)
            for c in self.usage.get("categories") or []:
                if int(c.get("tokens") or 0) <= 0 or c.get("kind") == "free":
                    continue
                cr = QHBoxLayout()
                cr.setSpacing(8)
                tone = cat_tone(c)
                sw = Box(bg=f"{tone}/canvas" if tone else None, radius=2)
