echo "Added Pilcrow to the applications menu."
case ":$PATH:" in
  *":$BIN:"*) echo "Run it from a terminal with: pilcrow" ;;
  *) echo "Run it from a terminal with: $BIN/pilcrow   (add ~/.local/bin to PATH to type just 'pilcrow')" ;;
esac
