function candidates(base) {
  const out = [`${base}/v1/models`];
  if (/\/v1$/.test(base)) out.push(`${base}/models`);
  try {
    const u = new URL(base);
    if (u.pathname.replace(/\/+$/, '')) out.push(`${u.origin}/v1/models`);
  } catch {
    /* invalid base: the first attempt reports it */
