async function fetchList(listUrl, headers, env) {
  const models = [];
  const seen = new Set();
  let after = null;
  for (let page = 0; page < 20; page++) {
    let url;
    try {
      url = new URL(listUrl);
    } catch {
      return { ok: false, error: `Not a valid URL: ${listUrl}` };
