    this.held = this.held.filter((h) => h.uuid !== u);
    if (this.held.length !== n) this.emitState();
    return this.held.length !== n;
  }

  updateHeld(u, text) {
    const h = this.held.find((h) => h.uuid === u);
    if (!h) return false;
    h.text = text;
    this.emitState();
    return true;
  }

