      }
    }
    this.emitState();
  }

  async setModel(model) {
    this.model = model || '';
    store.setMeta(this.id, { model: this.model || null });
    if (this.q) await this.q.setModel(model || undefined);
    this.emitState();
  }

  async setEffort(effort) {
    this.effort = effort || '';
    store.setMeta(this.id, { effort: this.effort || null });
