 * @param {{ id: string, cwd: string }} session
 * @param {StepInput} what
 */
export function record(session, what) {
  return serial(session.cwd, () => take(session, what)).catch((e) => {
    log('timeline failed', session.id, e?.message);
    return null;
  });
