      },
    },
    {
      label: 'Save as playbook',
      icon: BookMarked,
      onSelect: async () => {
        await call('dispatch.savePlaybook', { fromJob: id, name: job.name }).catch(() => null);
        loadPlaybooks();
        toast(`Saved as playbook: ${job.name}`, 'success');
      },
    },
    {
      label: 'Schedule this…',
      icon: CalendarClock,
      onSelect: async () => {
