      try {
        const g = await call<GitInfo>('git.info', { cwd }, { quiet: true });
        setGit(g);
        if (g.isRepo) {
          const b = await call<{ current: string | null; list: { name: string }[] }>('git.branches', { cwd }, { quiet: true });
          setBranches(b.list);
          setBase(b.current || b.list[0]?.name || 'HEAD');
