  useEscape(onClose, open);
  useEffect(() => {
    if (!open) return;
    // Pointer, not mouse: a touch or a pen outside closes it too.
    const onDown = (e: PointerEvent) => {
      if (ref.current?.contains(e.target as Node) || anchor?.contains?.(e.target as Node)) return;
