  toml: 'TOML', md: 'Markdown', markdown: 'Markdown', html: 'HTML', css: 'CSS', scss: 'SCSS', sql: 'SQL', c: 'C', h: 'C', cpp: 'C++', 'c++': 'C++', cc: 'C++', hpp: 'C++',
