  r: 'R', matlab: 'MATLAB', lua: 'Lua', xml: 'XML', ini: 'INI', text: 'Text', txt: 'Text', plaintext: 'Text', csv: 'CSV', graphql: 'GraphQL', proto: 'Protobuf',
