      snappy: token('--spring-snappy', EASE),
      snappyT: parseInt(token('--spring-snappy-t', '600'), 10) || 600,
      bouncy: token('--spring-bouncy', EASE),
      bouncyT: parseInt(token('--spring-bouncy-t', '760'), 10) || 760,
