      last.current = Date.now();
      setShown(value);
      return;
    }
    if (timer.current == null) {
      timer.current = window.setTimeout(() => {
        timer.current = null;
        last.current = Date.now();
        setShown(latest.current);
      }, due);
    }
  }, [value, ms]);
