}

/* ---- buttons
   Default buttons are quiet fills; one primary (amber) per surface. Every press gives a 2% squeeze. */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-1_5);
  height: 30px;
  padding: 0 var(--sp-3);
  border-radius: var(--r-2);
  background: var(--fill-2);
  color: var(--text);
  font-weight: 500;
  white-space: nowrap;
}
.btn:hover {
  background: var(--fill-3);
}
.btn:disabled {
