}
.switch.on::after {
  transform: translateX(14px);
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  height: 19px;
  padding: 0 var(--sp-1_75);
  border-radius: var(--r-pill);
