  background: var(--ok-wash);
}
.badge.err {
  color: var(--err);
  background: var(--err-wash);
}
.badge.plan {
  color: var(--plan);
  background: var(--plan-wash);
}
.badge.info {
  color: var(--info);
  background: var(--info-wash);
}

.num-add,
.num-del {
  font-family: var(--font-mono);
  font-size: var(--fs-micro-plus);
  font-variant-numeric: tabular-nums;
}
.num-add {
  color: var(--ok);
}
.num-del {
  color: var(--err);
}
.num-add.zero,
.num-del.zero {
  color: var(--text-3);
}

.empty {
  display: grid;
  place-items: center;
  gap: var(--sp-2);
  padding: var(--sp-11) var(--sp-5);
  text-align: center;
  color: var(--text-3);
  line-height: 1.55;
}

/* Something on its way (ui/Empty Loading): faint lines with a slow sheen where rows will be. */
.loading-rows {
  display: grid;
  gap: var(--sp-5_5);
  padding: var(--sp-4) var(--sp-3_5);
}
.sk-row {
  display: grid;
  gap: var(--sp-2_25);
}
.sk-row .sk {
  height: 11px;
}
.sk {
  height: 14px;
  border-radius: var(--r-pill);
  background: linear-gradient(90deg, var(--fill-1), var(--fill-2), var(--fill-1));
  background-size: 200% 100%;
}
.sk.short {
  width: 60%;
}

/* A part of the page that failed to render (ui/ErrorBoundary.tsx): says so in place, offers a retry. */
.render-fault {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-2) var(--sp-3);
  border-radius: var(--r-2);
  color: var(--err);
  background: var(--err-wash);
  font-size: var(--fs-small);
}
.render-fault-text {
  flex: 1;
  min-width: 0;
}
.render-fault-why {
  color: var(--text-3);
}
.render-fault-retry {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  color: var(--text-2);
}
