/* ================================================================ dialogs
   Dialogs: the sheet and its parts, the new-session dialog, the segmented control, the palette,
   the shortcuts sheet, and toasts. */

/* ================================================================ dialogs */

.scrim {
  position: fixed;
  inset: 0;
  z-index: var(--z-dialog);
  display: grid;
  place-items: start center;
  padding: 9vh var(--sp-5) var(--sp-5);
  background: var(--scrim);
  -webkit-backdrop-filter: var(--scrim-blur);
  backdrop-filter: var(--scrim-blur);
  overflow-y: auto;
}
.dialog {
  max-width: 100%;
  display: flex;
  flex-direction: column;
  max-height: min(88vh, 860px);
  border-radius: var(--r-7);
  background: var(--glass-2);
  -webkit-backdrop-filter: var(--glass-blur);
  backdrop-filter: var(--glass-blur);
  box-shadow: var(--shadow-sheet);
}
/* A sheet with no field takes the focus itself, for a screen reader to read it from the title; it needs no ring. */
.dialog:focus-visible {
  outline: none;
}
.dialog-head {
  display: flex;
  align-items: center;
  gap: var(--sp-2_5);
  padding: var(--sp-4_5) var(--sp-4) var(--sp-1_5) var(--sp-5_5);
}
.dialog-title {
  flex: 1;
  font-size: var(--fs-h);
  font-weight: 600;
  letter-spacing: -0.01em;
}
.dialog-body {
  padding: var(--sp-2_5) var(--sp-5_5) var(--sp-5);
  overflow-y: auto;
  display: grid;
  gap: var(--sp-4_5);
  align-content: start;
}
.dialog-foot {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-3_5) var(--sp-4_5) var(--sp-4) var(--sp-5_5);
  box-shadow: 0 -1px 0 var(--hair);
}
.err-text {
  font-size: var(--fs-small);
  color: var(--err);
  line-height: 1.45;
}
.confirm-body {
  margin: 0;
  color: var(--text-2);
  line-height: 1.6;
}
.confirm-list {
  margin: -6px 0 0;
  padding: var(--sp-2) var(--sp-3);
  list-style: none;
  border-radius: var(--r-2);
  background: var(--inset);
  font-size: var(--fs-small);
  line-height: 1.75;
  max-height: 220px;
  overflow: auto;
}
.check {
  display: flex;
  align-items: center;
  gap: var(--sp-2_25);
  font-size: var(--fs-ui);
  color: var(--text-2);
  cursor: pointer;
}
.check input {
  width: 15px;
  height: 15px;
  accent-color: var(--text);
}

.chips {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--sp-1_5);
}
.chips-label {
  margin-right: var(--sp-0_5);
  font-size: var(--fs-micro);
  color: var(--text-3);
}
.folder-chip,
.chip {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1_25);
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  height: 26px;
  padding: 0 var(--sp-2_75);
  border-radius: var(--r-pill);
  font-size: var(--fs-small);
  color: var(--text-2);
  background: var(--fill-1);
  box-shadow: inset 0 0 0 1px var(--hair);
}
.chip {
  height: 24px;
  padding: 0 var(--sp-2_25);
  border-radius: var(--r-5);
  font-size: var(--fs-micro-plus);
}
.folder-chip:hover,
button.chip:hover {
  background: var(--fill-2);
  color: var(--text);
}
.folder-chip.on,
.chip.on {
  color: var(--text);
  background: var(--fill-2);
  box-shadow: inset 0 0 0 1px var(--hair-3);
}

.browser {
  border-radius: var(--r-4);
  background: var(--inset);
  box-shadow: inset 0 0 0 1px var(--hair);
  overflow: hidden;
}
.browser-head {
  display: flex;
  align-items: center;
  gap: var(--sp-1);
  padding: var(--sp-1_5) var(--sp-2_5) var(--sp-1_5) var(--sp-1_5);
  font-size: var(--fs-small);
  color: var(--text-2);
  box-shadow: 0 1px 0 var(--hair);
}
.browser-list {
  max-height: 220px;
  overflow-y: auto;
  padding: var(--sp-1);
}
.browser-item {
  display: flex;
  align-items: center;
  gap: var(--sp-2_25);
  width: 100%;
  height: 30px;
  padding: 0 var(--sp-2);
  border-radius: var(--r-2);
  text-align: left;
  color: var(--text-2);
}
.browser-item:hover {
  background: var(--fill-2);
  color: var(--text);
}
.browser-item svg:first-child {
  color: var(--text-3);
}
.browser-empty {
  padding: var(--sp-2_5);
  font-size: var(--fs-small);
}

/* new session */
.newsession .dialog-body {
  gap: var(--sp-4_5);
}
.ns-section {
  display: grid;
  gap: var(--sp-2);
}
.ns-prompt {
  min-height: 64px;
}
.ns-label {
  font-size: var(--fs-small);
  font-weight: 600;
  color: var(--text-2);
}
.ns-folder {
  display: flex;
  align-items: center;
  gap: var(--sp-1);
  height: 40px;
  padding: 0 var(--sp-1_25) 0 var(--sp-3);
  border-radius: var(--r-4);
  background: var(--fill-1);
  box-shadow: inset 0 0 0 1px var(--hair);
}
.ns-folder:focus-within {
  background: var(--canvas);
  box-shadow: inset 0 0 0 1px var(--hair-3), 0 0 0 3px var(--fill-1);
}
.ns-folder-ico {
  color: var(--text-3);
  margin-right: var(--sp-1);
}
.ns-folder-input {
  flex: 1;
  min-width: 0;
  border: none;
  outline: none;
  background: transparent;
  font-size: var(--fs-small-plus);
}
.ns-folder .btn.on {
  background: var(--fill-2);
  color: var(--text);
}
.ns-row {
  display: flex;
  align-items: center;
  gap: var(--sp-4);
}
.ns-row-title {
  font-weight: 550;
  margin-bottom: var(--sp-0_5);
}
