/* ================================================================ menus
   Popovers, menus, the themed select, and tooltips (lib/tooltips.ts). */

/* ================================================================ popovers and menus */

.popover {
  position: fixed;
  z-index: var(--z-popover);
  min-width: 180px;
  max-height: min(70vh, 520px);
  overflow-y: auto;
  padding: var(--sp-1_25);
  border-radius: var(--r-4);
  background: var(--glass);
  -webkit-backdrop-filter: var(--glass-blur);
  backdrop-filter: var(--glass-blur);
  box-shadow: var(--shadow-glass);
}

.menu {
  display: grid;
  gap: 1px;
}
.menu-item {
  display: flex;
  align-items: flex-start;
  gap: var(--sp-2_25);
  width: 100%;
  min-height: 30px;
  padding: var(--sp-1_5) var(--sp-2_25);
  border-radius: var(--r-2);
  text-align: left;
  color: var(--text);
  font-size: var(--fs-ui);
}
.menu-item.active {
  background: var(--fill-2);
}
/* the lit row is the focus indicator in a menu */
.menu-item:focus-visible {
  outline: none;
}
.menu-item:disabled {
  color: var(--text-3);
  cursor: default;
  background: none;
}
.menu-item.danger {
  color: var(--err);
}
.menu-icon {
  flex: none;
  display: grid;
  place-items: center;
  width: 16px;
  height: 18px;
  color: var(--text-3);
}
.menu-item.active .menu-icon {
  color: var(--text-2);
}
.menu-item.danger .menu-icon {
  color: var(--err);
}
.menu-text {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: var(--sp-0_5);
}
.menu-label {
  line-height: 18px;
}
.menu-hint {
  font-size: var(--fs-small);
  line-height: 1.4;
  color: var(--text-3);
}
.menu-hint.mono {
  font-family: var(--font-mono);
  font-size: var(--fs-micro-plus);
  overflow-wrap: anywhere;
}
.menu-item kbd {
  background: none;
  box-shadow: none;
  color: var(--text-3);
}
/* on the lit row's fill the faint inks fall short of 4.5:1 (tokens.css) */
.menu-item.active .menu-hint,
.menu-item.active kbd {
  color: var(--text);
}
.menu-sep {
  height: 1px;
  margin: var(--sp-1) var(--sp-1_5);
  background: var(--hair);
}
.menu-heading {
  padding: var(--sp-2) var(--sp-2_25) var(--sp-1);
  font-size: var(--fs-micro);
  font-weight: 600;
  color: var(--text-3);
}

/* themed <select> replacement */
.select-btn {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  width: 100%;
  height: 34px;
  padding: 0 var(--sp-2_5) 0 var(--sp-2_75);
  border-radius: var(--r-2);
  background: var(--fill-1);
  box-shadow: inset 0 0 0 1px var(--hair);
  text-align: left;
}
.select-btn:hover,
.select-btn[aria-expanded='true'] {
  box-shadow: inset 0 0 0 1px var(--hair-2);
  background: var(--fill-2);
}
.select-ico,
.select-chev {
  color: var(--text-3);
}
.select-btn.ghost-select {
  width: auto;
  height: 26px;
  padding: 0 var(--sp-1_5) 0 var(--sp-2);
  background: transparent;
  box-shadow: none;
  font-size: var(--fs-small);
  font-weight: 550;
}
.select-btn.ghost-select:hover,
.select-btn.ghost-select[aria-expanded='true'] {
  background: var(--fill-2);
  box-shadow: none;
}

/* ================================================================ tooltips (lib/tooltips.ts) */

.tip {
  position: fixed;
  z-index: var(--z-tip);
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  max-width: 320px;
  padding: var(--sp-1_25) var(--sp-2);
  border-radius: 7px;
  font-size: var(--fs-small);
  line-height: 1.4;
  font-weight: 500;
  color: var(--tip-ink);
  background: var(--tip);
  box-shadow: var(--shadow-tip);
  white-space: pre-line;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-3px) scale(0.98);
}
.tip[data-side='top'] {
  transform: translateY(3px) scale(0.98);
}
.tip.show {
  opacity: 1;
  transform: none;
}
.tip-keys {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-0_75);
}
.tip-note {
  margin-left: var(--sp-0_75);
  color: color-mix(in srgb, var(--tip-ink) 62%, var(--tip));
  font-weight: 400;
}
.tip kbd {
  min-width: 18px;
  height: 18px;
  padding: 0 var(--sp-1_25);
  border-radius: var(--r-1);
  font-family: var(--font-ui);
  font-size: var(--fs-tiny-plus);
  font-weight: 600;
  color: color-mix(in srgb, var(--tip-ink) 80%, var(--tip));
  background: color-mix(in srgb, var(--tip-ink) 10%, transparent);
  box-shadow: none;
}
